reactions.activationCode:
const targetToken = triggerData.triggeringToken;
if (!targetToken) return;

// 기록 초기화
const flagKey = "recordedLockonTokens";
let recorded = reactorToken.actor.getFlag("world", flagKey) || [];
recorded = recorded.filter(id => id !== targetToken.id);
await reactorToken.actor.setFlag("world", flagKey, recorded);

// 소유자 ID 가져오기
const ownerIds = api.getTokenOwnerUserId(reactorToken);

// 영어 UI가 적용된 초이스 카드 생성
await api.startChoiceCard({
    mode: "or",
    userIdControl: ownerIds,
    title: "AUTONOMOUS ASSAULT",
    description: `Do you want to automatically hit ${targetToken.name} with the Autopod?`,
    icon: "fas fa-crosshairs",
    choices: [
        {
            text: "Yes",
            icon: "fas fa-bomb",
            callback: async () => {
                // Sequencer 애니메이션 실행
                const wfx = game.modules.get("lancer-weapon-fx")?.api;

                if (wfx && globalThis.Sequencer) {
                    await Sequencer.Preloader.preloadForClients([
                        "modules/lancer-weapon-fx/soundfx/Autopod_Fire.ogg",
                        "jb2a.template_circle.vortex.loop.blue",
                        "modules/lancer-weapon-fx/soundfx/Autopod_Impact.ogg",
                        "jb2a.impact.yellow.1",
                    ]);

                    let sequence = new Sequence();

                    sequence
                        .sound()
                        .file("modules/lancer-weapon-fx/soundfx/Autopod_Fire.ogg")
                        .volume(wfx.getEffectVolume(0.7))
                        .effect()
                        .xray(wfx.isEffectIgnoreFogOfWar())
                        .aboveInterface(wfx.isEffectIgnoreLightingColoration())
                        .file("jb2a.template_circle.vortex.loop.blue")
                        .endTime(4700)
                        .scale(0.2)
                        .tint("#787878")
                        .atLocation(reactorToken)
                        .moveTowards(targetToken)
                        .waitUntilFinished()
                        .sound()
                        .file("modules/lancer-weapon-fx/soundfx/Autopod_Impact.ogg")
                        .volume(0.7)
                        .effect()
                        .xray(wfx.isEffectIgnoreFogOfWar())
                        .aboveInterface(wfx.isEffectIgnoreLightingColoration())
                        .file("jb2a.impact.yellow.1")
                        .scale(0.6)
                        .atLocation(targetToken);

                    await sequence.play();
                }

                // 데미지 롤 API 실행
                if (typeof api.executeDamageRoll === "function") {
                    await api.executeDamageRoll(
                        reactorToken,
                        [targetToken],
                        3,
                        "kinetic",
                        "Autonomous Assault Damage"
                    );
                } else if (targetToken.actor && typeof targetToken.actor.applyDamage === "function") {
                    await targetToken.actor.applyDamage(3, "kinetic");
                }

                ui.notifications.info(`Successfully attacked ${targetToken.name} with Autopod!`);
            }
        },
        {
            text: "No",
            icon: "fas fa-times",
            callback: async () => {
                ui.notifications.info("Autonomous assault canceled.");
            }
        }
    ]
});

const targets = await api.chooseToken(reactorToken, {
    title: "FALSE IDOL // SELECT TARGET",
    description: "Select yourself or an allied character within Sensors.",
    range: 'sensors',
    disposition: 'friendly',
    includeSelf: true
});

if (!targets || !targets.length) return;
const original = targets[0];

const idolTokens = await api.placeToken({
    actor: original.actor,
    origin: reactorToken,
    range: api.getSensorRange_WithBonus(reactorToken),
    count: 1,
    title: "PLACE FALSE IDOL",
    extraData: {
        name: `False Idol (${original.name})`,
        alpha: 0.6, 
        actorLink: false, 
        "texture.tint": "#4a9eff", 
        "system.hp.max": 1,
        "system.hp.value": 1,
        "system.evasion": 10,
        "system.edef": 10
    }
});

if (!idolTokens || !idolTokens.length) return; 
const idolDoc = idolTokens[0];

const previousIdolId = api.getTokenFlags(reactorToken, "false_idol_tokenId");
await api.addTokenFlags(reactorToken, {
    "false_idol_tokenId": idolDoc.id,
});

// delete previous idol
if (previousIdolId) {
    const previousIdol = canvas.tokens.get(previousIdolId);
    if (previousIdol) await previousIdol.document.delete();
};

reactions.evaluate:
const idolId = api.getTokenFlags(reactorToken, "false_idol_tokenId");
const idolToken = canvas.tokens.get(idolId);
if (!idolToken) return false;

const target = triggerData.triggeringToken
const immune = api.getTokenFlags(target, "false_idol_immune");
if (immune == idolId) return false;

return api.hasLineOfSight(target, idolToken);

reactions.activationCode:
const idolId = api.getTokenFlags(reactorToken, "false_idol_tokenId");
const target = triggerData.triggeringToken

await api.executeSaveVsEffect(
    [target], 
    {
        stat: "SYS",
        title: "False Idol // Systems Save",
        origin: reactorToken, 
        sendToOwner: true,
        effects: { 
            name: "Deceived", 
            icon: "modules/lancer-automations/icons/dazed.svg", 
            isCustom: true 
        },

        duration: { 
            label: 'end', 
            turns: 1, 
        },
    });

await api.addTokenFlags(target, {"false_idol_immune": idolId});

for (const target of triggerData.hitTokens) {
    const speed = api.tokenSpeed(target);
    await api.knockBackToken([target], speed, { 
        triggeringToken: reactorToken,
        title: "// PUPPET SYSTEMS //",
        description: "Select destination to move the target to."
    });

}

await api.applyEffectsToTokens({
    tokens: triggerData.hitTokens,
    effectNames: ["jammed"],
    duration: {
        label: "end",
        turns: 1,
        rounds: 0,
    }
});

const hitTokens = triggerData.targets.map(hit => hit.target);
await api.executeDamageRoll(reactorToken, hitTokens, 2, 'Heat', 'Hurl into the Duat');

let currentGate = api.getActorFlags(reactorToken.actor, 'duat_gate') || 1;

const postChat = (title, text) => {
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ token: reactorToken.document }),
        content: `
        <div class="card clipped-bot" style="margin:0px">
            <div class="lancer-header lancer-primary">
                <span>// ${title} //</span>
            </div>
            <div style="padding:5px">
                <div class="effect-text">
                    ${text}
                </div>
            </div>
        </div>`,
    });
}

for (const hitResult of triggerData.targets) {
    const target = hitResult.target;
    const duration = api.untilEndOfTurn(target);
    let message = "";

    if (currentGate === 1) {
        await postChat("FIRST GATE", `${reactorToken.name} controls ${target.name}'s standard move on their next turn.`);
    } 
    else if (currentGate === 2) {
        await postChat("SECOND GATE", `${target.name} is Slowed and Impaired until the end of their next turn.`);
        await api.applyEffectsToTokens({
            tokens: [target],
            effectNames: ['slow', 'impaired'],
            duration: duration,
            note: "Second Gate"
        });
    } 
    else if (currentGate === 3) {
        await postChat("THIRD GATE", `${target.name} is Stunned until the end of their next turn.`);
        await api.applyEffectsToTokens({
            tokens: [target],
            effectNames: ['stunned'],
            duration: duration,
            note: "Third Gate"
        });
    } 
    else if (currentGate === 4) {
        await postChat("FOURTH GATE", `${target.name} changes allegiance temporarily, becoming an allied character until the end of their next turn. They treat your allied characters and hostile characters as their own and are treated as an allied NPC for activation and turn order. This effect ends immediately if you or any allied character damages, inflicts heat upon, or attacks (including Grapple and Ram) your target, or forces them to make a save.`);
    }
}

currentGate = (currentGate % 4) + 1;

await api.addActorFlags(reactorToken.actor, { duat_gate: currentGate });

